        };
        let mut attributes = QueueAttributes::from_patch(
            &AttributePatch {
                fifo: Some(true),
                ..AttributePatch::default()
            },
            Some(dead_letter.clone()),
        );
        attributes.apply(
            &AttributePatch {
                delay: Some(Seconds(9)),
                content_based_deduplication: Some(true),
