        };
        let only_count = AttributePatch {
            max_receive_count: Some(2),
            ..AttributePatch::default()
        };
        for patch in [only_queue, only_count] {
            let error = patch.dead_letter().unwrap_err();
            assert_eq!(error.code(), ErrorCode::InvalidParameterValue);
        }
    }

