            return Ok(original.into());
        }
        if queue.is_full() {
            return Err(Error::new(
                ErrorCode::LimitExceeded,
                "a queue holds at most 100000 messages",
            ));
        }
        let delay = delay.unwrap_or(queue.attributes().delay);
        let accepted = queue.append(Incoming {
            id: self.ids.next_message(),
            body,
            sent_at: now,
            delayed_until: now.plus(delay),
            group,
        });
        if let Some(key) = dedup_key {
            queue.remember(key, now, accepted);
        }
        Ok(accepted.into())
    }

    fn receive_message(
        &mut self,
        name: &str,
        max_messages: usize,
        visibility_timeout: Option<Seconds>,
    ) -> Result<Reply, Error> {
        let now = self.now;
        let queue = Self::live_queue(&mut self.queues, name, now)?;
        let visibility = visibility_timeout.unwrap_or(queue.attributes().visibility_timeout);
